PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS v2_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sports (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sport_aliases (sport_id TEXT NOT NULL REFERENCES sports(id) ON DELETE CASCADE, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL UNIQUE, source TEXT, PRIMARY KEY (sport_id, normalized_alias));
CREATE TABLE IF NOT EXISTS competitions (id TEXT PRIMARY KEY, sport_id TEXT NOT NULL REFERENCES sports(id), name TEXT NOT NULL, country TEXT, season TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS participants (id TEXT PRIMARY KEY, sport_id TEXT REFERENCES sports(id), participant_type TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS participant_aliases (participant_id TEXT NOT NULL REFERENCES participants(id) ON DELETE CASCADE, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL, source TEXT, PRIMARY KEY (participant_id, normalized_alias));
CREATE INDEX IF NOT EXISTS idx_participant_alias_norm ON participant_aliases(normalized_alias);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, sport_id TEXT NOT NULL REFERENCES sports(id), competition_id TEXT REFERENCES competitions(id), name TEXT NOT NULL, starts_at TEXT NOT NULL, home_participant_id TEXT REFERENCES participants(id), away_participant_id TEXT REFERENCES participants(id), venue TEXT, status TEXT NOT NULL DEFAULT 'scheduled', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_events_start ON events(starts_at);
CREATE INDEX IF NOT EXISTS idx_events_sport ON events(sport_id);
CREATE TABLE IF NOT EXISTS event_source_ids (event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, source_name TEXT NOT NULL, source_event_id TEXT NOT NULL, PRIMARY KEY (source_name, source_event_id));
CREATE TABLE IF NOT EXISTS bookmakers (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookmaker_aliases (bookmaker_id TEXT NOT NULL REFERENCES bookmakers(id) ON DELETE CASCADE, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL UNIQUE, PRIMARY KEY (bookmaker_id, normalized_alias));
CREATE TABLE IF NOT EXISTS sources (name TEXT PRIMARY KEY, kind TEXT NOT NULL, cost TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, health TEXT NOT NULL DEFAULT 'unknown', sports_json TEXT NOT NULL DEFAULT '[]', capabilities_json TEXT NOT NULL DEFAULT '[]', notes TEXT, last_ok_at TEXT, last_error_at TEXT, last_error TEXT);
CREATE TABLE IF NOT EXISTS source_fetch_log (id INTEGER PRIMARY KEY AUTOINCREMENT, source_name TEXT NOT NULL REFERENCES sources(name), requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, sport TEXT, capability TEXT, request_key TEXT, cache_hit INTEGER NOT NULL DEFAULT 0, success INTEGER NOT NULL DEFAULT 0, paid INTEGER NOT NULL DEFAULT 0, reason TEXT, error TEXT);
CREATE INDEX IF NOT EXISTS idx_source_fetch_time ON source_fetch_log(requested_at);
CREATE TABLE IF NOT EXISTS markets (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, kind TEXT NOT NULL, label TEXT NOT NULL, metric TEXT, line TEXT, period TEXT NOT NULL DEFAULT 'full_event', participant_id TEXT REFERENCES participants(id), settlement_rule_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS selections (id TEXT PRIMARY KEY, market_id TEXT NOT NULL REFERENCES markets(id) ON DELETE CASCADE, label TEXT NOT NULL, side TEXT, participant_id TEXT REFERENCES participants(id));
CREATE TABLE IF NOT EXISTS odds_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, market_id TEXT NOT NULL REFERENCES markets(id) ON DELETE CASCADE, selection_id TEXT NOT NULL REFERENCES selections(id) ON DELETE CASCADE, bookmaker_id TEXT REFERENCES bookmakers(id), decimal_odds TEXT NOT NULL, captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, source_name TEXT, source_age_seconds INTEGER, bookmaker_market_label TEXT, bookmaker_selection_label TEXT);
CREATE INDEX IF NOT EXISTS idx_odds_lookup ON odds_snapshots(event_id, market_id, bookmaker_id, captured_at);
CREATE TABLE IF NOT EXISTS research_evidence (id TEXT PRIMARY KEY, event_id TEXT REFERENCES events(id) ON DELETE CASCADE, sport_id TEXT REFERENCES sports(id), evidence_type TEXT NOT NULL, subject TEXT, summary TEXT NOT NULL, source_name TEXT, source_url TEXT, observed_at TEXT, fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, freshness_seconds INTEGER, reliability TEXT, raw_json TEXT);
CREATE TABLE IF NOT EXISTS picks_v2 (id TEXT PRIMARY KEY, legacy_bet_id TEXT, event_id TEXT NOT NULL REFERENCES events(id), market_id TEXT NOT NULL REFERENCES markets(id), selection_id TEXT NOT NULL REFERENCES selections(id), bookmaker_id TEXT REFERENCES bookmakers(id), decimal_odds TEXT NOT NULL, confidence_pct REAL, rationale TEXT, strategy TEXT, selected INTEGER NOT NULL DEFAULT 0, outcome TEXT NOT NULL DEFAULT 'pending', stake TEXT, payout TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, settled_at TEXT);
CREATE INDEX IF NOT EXISTS idx_picks_outcome ON picks_v2(outcome);
CREATE INDEX IF NOT EXISTS idx_picks_created ON picks_v2(created_at);
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, bookmaker_id TEXT REFERENCES bookmakers(id), source_type TEXT NOT NULL, source_reference TEXT, parent_ticket_id TEXT REFERENCES tickets(id), version_no INTEGER NOT NULL DEFAULT 1, booking_code TEXT, status TEXT NOT NULL DEFAULT 'draft', combined_odds TEXT, stake TEXT, payout TEXT, notes_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, settled_at TEXT);
CREATE TABLE IF NOT EXISTS ticket_legs (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, leg_no INTEGER NOT NULL, event_id TEXT NOT NULL REFERENCES events(id), market_id TEXT NOT NULL REFERENCES markets(id), selection_id TEXT NOT NULL REFERENCES selections(id), bookmaker_id TEXT REFERENCES bookmakers(id), decimal_odds TEXT NOT NULL, locked INTEGER NOT NULL DEFAULT 0, outcome TEXT NOT NULL DEFAULT 'pending', note TEXT, UNIQUE(ticket_id, leg_no));
CREATE TABLE IF NOT EXISTS bankroll_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, kind TEXT NOT NULL, amount TEXT NOT NULL, balance_after TEXT, pick_id TEXT REFERENCES picks_v2(id), ticket_id TEXT REFERENCES tickets(id), legacy_bet_id TEXT, note TEXT);
CREATE INDEX IF NOT EXISTS idx_bankroll_time ON bankroll_ledger(occurred_at);
CREATE TABLE IF NOT EXISTS settlement_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, previous_outcome TEXT, new_outcome TEXT NOT NULL, source TEXT NOT NULL, reason TEXT, changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blog_posts (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, body TEXT NOT NULL, excerpt TEXT, category TEXT, tags_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'draft', related_json TEXT NOT NULL DEFAULT '{}', published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jobs (name TEXT PRIMARY KEY, description TEXT, enabled INTEGER NOT NULL DEFAULT 1, expected_interval_seconds INTEGER, last_started_at TEXT, last_finished_at TEXT, last_success_at TEXT, last_error_at TEXT, last_error TEXT, consecutive_failures INTEGER NOT NULL DEFAULT 0);
